#!/usr/bin/env python3
"""Replace the tabular bodies of the tables that now carry the final M3 in psc_manuscript/ml.tex with the rows generated by
scripts/make_t3_tables.py (results/t3final_summary/table_rows.json). Captions are edited by hand in ml.tex."""
import json, re
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
tex = ROOT / "psc_manuscript/ml.tex"; s = tex.read_text()
rows = json.load(open(ROOT / "results/t3final_summary/table_rows.json"))
M1, M2, M3 = r"\mathcal{M}_1", r"\mathcal{M}_2", r"\mathcal{M}_3"
HEAD = {
 "tab:tiers": (r"\begin{tabular}{llrrccc}", f"Subset & Feature tier & $N$ & Feat. & $R^2$ & MAE & RMSE \\\\"),
 "tab:delta": (r"\begin{tabular}{lcccccccc}", None),
 "tab:split": (r"\begin{tabular}{llccccc}", "Model & Feature tier & $R^2$ random & $R^2$ DOI-grouped & Gap & MAE rand. & MAE DOI \\\\"),
 "tab:strict": (r"\begin{tabular}{llrrccccc}", f"Protocol & Model & $N_\\mathrm{{test}}$ & Splits & ${M1}$ & ${M2}$ & ${M3}$ & MAE (${M2}$) & MAE (${M3}$) \\\\"),
 "tab:temporal": (r"\begin{tabular}{rllrrrrr}", f"Win. & Train until & Test from & $n_\\mathrm{{train}}$ & $n_\\mathrm{{test}}$ & ${M1}$ & ${M2}$ & ${M3}$ \\\\"),
 "tab:t3protocols": (r"\begin{tabular}{llcrccccrc}",
   f"Protocol & Model & Test records & $N$ & $R^2$ ${M2}$ & $R^2$ ${M3}$ & $\\Delta R^2$ & $\\Delta$MAE & Splits $\\Delta>0$ & CI $>0$/$<0$ \\\\"),
}
def build(label):
    begin, head = HEAD[label]
    if label == "tab:delta":
        body = (r"\begin{tabular}{lcccccccc}" "\n        \\toprule\n"
                f"        & \\multicolumn{{4}}{{c}}{{${M1}\\!\\to\\!{M2}$}} & \\multicolumn{{4}}{{c}}{{${M2}\\!\\to\\!{M3}$}} \\\\\n"
                "        \\cmidrule(lr){2-5}\\cmidrule(lr){6-9}\n"
                "        Subset & $\\Delta R^2$ & $\\Delta$RMSE & better & CI$\\neq0$ & $\\Delta R^2$ & $\\Delta$RMSE & better & CI$\\neq0$ \\\\\n"
                "        \\midrule\n")
    else:
        body = begin + "\n        \\toprule\n        " + head + "\n        \\midrule\n"
    return body + "\n".join("        " + r for r in rows[label]) + "\n        \\bottomrule\n    \\end{tabular}"
for label in HEAD:
    if label == "tab:t3protocols" and f"\\label{{{label}}}" not in s: continue
    m = re.search(r"\\label\{" + re.escape(label) + r"\}.*?(\\begin\{tabular\}.*?\\end\{tabular\})", s, re.S)
    assert m, label
    s = s[:m.start(1)] + build(label) + s[m.end(1):]
tex.write_text(s); print("patched")
